def simplify_exact(expr):
    import sympy as sp
    e = sp.nsimplify(sp.sympify(expr), [sp.pi, sp.E], rational=False) if isinstance(expr, (int, float)) \
        else sp.simplify(sp.sympify(expr))
    return str(e), sp.latex(e), float(sp.N(e))

