def terms(f, n, start=1):
    return [f(i) for i in range(start, start + n)]

def recurrence(rule, init, n):
    xs = list(init)
    while len(xs) < n:
        xs.append(rule(xs))
    return xs[:n]

def partial_sums(xs):
    out, s = [], 0
    for x in xs:
        s += x
        out.append(s)
    return out
